function rtInit(){ED=$('#fe');SR=null;document.execCommand('styleWithCSS',false,true);ED.addEventListener('input',rtDone);ED.addEventListener('paste',rtPaste);
 ED.addEventListener('drop',e=>{e.preventDefault();const tx=e.dataTransfer.getData('text/plain');if(tx){ED.focus();document.execCommand('insertText',false,tx);rtDone()}});rtDone()}
