function rtPaste(e){e.preventDefault();const cd=e.clipboardData,h=cd.getData('text/html'),tx=cd.getData('text/plain');
 if(h)document.execCommand('insertHTML',false,san(h).replace(/\sstyle="[^"]*"/g,''));else document.execCommand('insertText',false,tx);rtDone()}
function rtRestore(){if(!ED||!ED.isConnected)return false;ED.focus({preventScroll:true});if(SR){const s=getSelection();s.removeAllRanges();s.addRange(SR)}return true}
function rtDone(){if(!ED||!ED.isConnected)return;const s=getSelection();if(s.rangeCount&&ED.contains(s.anchorNode))SR=s.getRangeAt(0).cloneRange();ED.classList.toggle('empty',!ED.textContent.replace(/\u200B/g,'').trim()&&!ED.querySelector('li'));rtState()}
const ex=(c,v)=>{if(!rtRestore())return;document.execCommand('styleWithCSS',false,true);document.execCommand(c,false,v);rtDone()};
// تطبيق خط/حجم/لون: على النص المحدد، أو على اللي هتكتبه بعد المؤشر
function rtSet(prop,val){if(!rtRestore())return;const s=getSelection();if(!s.rangeCount)return;const r=s.getRangeAt(0);document.execCommand('styleWithCSS',false,true);
 if(r.collapsed){const sp=document.createElement('span');sp.style[prop]=val;sp.textContent='\u200B';r.insertNode(sp);const n=document.createRange();n.setStart(sp.firstChild,1);n.collapse(true);s.removeAllRanges();s.addRange(n)}
 else if(prop=='fontSize'){document.execCommand('fontSize',false,'7');const T=[];ED.querySelectorAll('font[size="7"]').forEach(f=>{const sp=document.createElement('span');sp.append(...f.childNodes);f.replaceWith(sp);T.push(sp)});ED.querySelectorAll('span').forEach(sp=>{if(sp.style.fontSize=='xxx-large')T.push(sp)});
  T.forEach(sp=>{sp.style.fontSize=val;sp.querySelectorAll('[style]').forEach(c=>{c.style.removeProperty('font-size');if(!c.getAttribute('style'))c.removeAttribute('style')})});
  ED.querySelectorAll('span:not([style])').forEach(sp=>sp.replaceWith(...sp.childNodes));
  if(T.length&&T[0].isConnected){const n=document.createRange();n.setStartBefore(T[0]);n.setEndAfter(T[T.length-1]);s.removeAllRanges();s.addRange(n)}}
 else document.execCommand(prop=='color'?'foreColor':prop=='backgroundColor'?'hiliteColor':'fontName',false,val);rtDone()}
