 const it=(oc,tx,st='',cl='')=>`<button type=button class="pit ${cl}" ${RTA} onclick="${oc}" style="${st}">${tx}</button>`,sw=(oc,c)=>`<button type=button class=sw2 ${RTA} onclick="${oc}" style="background:${c}" aria-label="${c}"></button>`;let h='';
